// Bài 11.3 — class Rectangle: dữ liệu trên từng thực thể, method trên prototype
class Rectangle {
  constructor(width, height) {
    this.width = width;
    this.height = height;
  }
  area() { return this.width * this.height; }
  perimeter() { return 2 * (this.width + this.height); }
  scale(k) {
    this.width *= k;
    this.height *= k;
    return this;               // trả chính object ⇒ nối được .area()
  }
}

